from __future__ import annotations

import json
from pathlib import Path

from .rig import Bone


def write_blender_script(
    output: Path,
    *,
    obj_path: Path,
    bones: list[Bone],
    group_to_bone: dict[str, str],
    smooth_weights: bool = True,
    glb_path: Path | None = None,
) -> None:
    data = {
        "obj": str(Path(obj_path).resolve()),
        "bones": [{"name": bone.name, "parent": bone.parent, "position": list(bone.position)} for bone in bones],
        "group_to_bone": group_to_bone,
        "smooth_weights": bool(smooth_weights),
        "glb_path": str(Path(glb_path).resolve()) if glb_path else None,
    }
    payload = json.dumps(data, ensure_ascii=False)
    script = f'''# Generated by Roblox Avatar Conversion Kit v0.2\nimport bpy, json, math, re\nfrom mathutils import Vector\n\nDATA = json.loads({payload!r})\n\ndef dist(a, b):\n    return (a - b).length\n\ndef point_segment_distance(p, a, b):\n    ab = b - a\n    denom = ab.length_squared\n    if denom <= 1e-12:\n        return (p - a).length\n    t = max(0.0, min(1.0, (p - a).dot(ab) / denom))\n    return (p - (a + ab * t)).length\n\ndef clean_obj_name(name):\n    base = re.sub(r"\\.\\d{{3}}$", "", name)\n    if base in DATA["group_to_bone"]:\n        return base\n    for group in DATA["group_to_bone"]:\n        if base.startswith(group):\n            return group\n    return base\n\nbpy.ops.object.select_all(action="SELECT")\nbpy.ops.object.delete(use_global=False)\n\ntry:\n    bpy.ops.wm.obj_import(filepath=DATA["obj"])\nexcept Exception:\n    bpy.ops.import_scene.obj(filepath=DATA["obj"])\n\nmeshes = [obj for obj in bpy.context.scene.objects if obj.type == "MESH"]\n\narm_data = bpy.data.armatures.new("RobloxAvatarRig")\narm_obj = bpy.data.objects.new("RobloxAvatarRig", arm_data)\nbpy.context.collection.objects.link(arm_obj)\nbpy.context.view_layer.objects.active = arm_obj\narm_obj.select_set(True)\nbpy.ops.object.mode_set(mode="EDIT")\ncreated = {{}}\nby_name = {{bone["name"]: bone for bone in DATA["bones"]}}\nchildren = {{name: [] for name in by_name}}\nfor spec in DATA["bones"]:\n    if spec["parent"] in children:\n        children[spec["parent"]].append(spec["name"])\n\nfor spec in DATA["bones"]:\n    bone = arm_data.edit_bones.new(spec["name"])\n    bone.head = Vector(spec["position"])\n    created[spec["name"]] = bone\n\nfor spec in DATA["bones"]:\n    bone = created[spec["name"]]\n    kids = children.get(spec["name"], [])\n    if kids:\n        child = min(kids, key=lambda name: dist(bone.head, Vector(by_name[name]["position"])))\n        tail = Vector(by_name[child]["position"])\n    elif spec["parent"] and spec["parent"] in by_name:\n        parent = Vector(by_name[spec["parent"]]["position"])\n        direction = bone.head - parent\n        tail = bone.head + (direction * 0.35 if direction.length > 1e-5 else Vector((0, 0.1, 0)))\n    else:\n        tail = bone.head + Vector((0, 0.1, 0))\n    if (tail - bone.head).length < 1e-4:\n        tail = bone.head + Vector((0, 0.1, 0))\n    bone.tail = tail\n\nfor spec in DATA["bones"]:\n    if spec["parent"]:\n        created[spec["name"]].parent = created.get(spec["parent"])\n\nbpy.ops.object.mode_set(mode="OBJECT")\n\nbone_pos = {{name: Vector(spec["position"]) for name, spec in by_name.items()}}\nsegments = {{}}\nfor name, spec in by_name.items():\n    kids = children.get(name, [])\n    if kids:\n        child = min(kids, key=lambda candidate: dist(bone_pos[name], bone_pos[candidate]))\n        segments[name] = (bone_pos[name], bone_pos[child])\n    elif spec["parent"] in bone_pos:\n        direction = bone_pos[name] - bone_pos[spec["parent"]]\n        segments[name] = (bone_pos[name], bone_pos[name] + direction * 0.35)\n    else:\n        segments[name] = (bone_pos[name], bone_pos[name] + Vector((0, 0.1, 0)))\n\ndef candidates(primary):\n    names = [primary]\n    spec = by_name.get(primary)\n    if spec and spec["parent"]:\n        names.append(spec["parent"])\n    names.extend(children.get(primary, []))\n    if primary in {{"hips", "spine", "chest", "neck"}}:\n        names.extend([name for name in ("hips", "spine", "chest", "neck") if name in by_name])\n    result = []\n    for name in names:\n        if name in by_name and name not in result:\n            result.append(name)\n    return result\n\ndef point_weights(point, primary):\n    scored = []\n    for name in candidates(primary):\n        a, b = segments[name]\n        length = max((b - a).length, 0.15)\n        distance = point_segment_distance(point, a, b)\n        score = 1.0 / ((distance + 0.20 * length) ** 2)\n        if name == primary:\n            score *= 1.35\n        scored.append((name, score))\n    scored.sort(key=lambda item: item[1], reverse=True)\n    scored = scored[:4]\n    total = sum(score for _, score in scored) or 1.0\n    normalized = [(name, score / total) for name, score in scored]\n    normalized = [(name, weight) for name, weight in normalized if weight >= 0.025] or [max(normalized, key=lambda item: item[1])]\n    total = sum(weight for _, weight in normalized) or 1.0\n    return [(name, weight / total) for name, weight in normalized]\n\nweighted_vertices = 0\nfor obj in meshes:\n    obj.parent = arm_obj\n    obj.modifiers.new(name="Armature", type="ARMATURE").object = arm_obj\n    group = clean_obj_name(obj.name)\n    primary = DATA["group_to_bone"].get(group)\n    if not primary:\n        continue\n    smooth = DATA["smooth_weights"] and group.lower().startswith("rig")\n    groups = {{}}\n    def vertex_group(name):\n        if name not in groups:\n            groups[name] = obj.vertex_groups.get(name) or obj.vertex_groups.new(name=name)\n        return groups[name]\n    if not smooth:\n        vertex_group(primary).add(list(range(len(obj.data.vertices))), 1.0, "REPLACE")\n        weighted_vertices += len(obj.data.vertices)\n        continue\n    for vertex in obj.data.vertices:\n        point = obj.matrix_world @ vertex.co\n        for bone_name, weight in point_weights(point, primary):\n            vertex_group(bone_name).add([vertex.index], weight, "REPLACE")\n        weighted_vertices += 1\n\nvrm_configured = False\ntry:\n    arm_data.vrm_addon_extension.spec_version = "1.0"\n    human = arm_data.vrm_addon_extension.vrm1.humanoid.human_bones\n    for name in ["hips","spine","chest","neck","head","leftUpperArm","leftLowerArm","leftHand","rightUpperArm","rightLowerArm","rightHand","leftUpperLeg","leftLowerLeg","leftFoot","rightUpperLeg","rightLowerLeg","rightFoot"]:\n        try:\n            getattr(human, name).node.bone_name = name\n        except Exception:\n            pass\n    vrm_configured = True\nexcept Exception:\n    pass\n\ndef arm_drop(side):\n    upper = bone_pos.get(side + "UpperArm")\n    lower = bone_pos.get(side + "LowerArm")\n    if not upper or not lower:\n        return None\n    vector = lower - upper\n    horizontal = abs(vector.x) + abs(vector.z)\n    return math.degrees(math.atan2(abs(vector.y), max(horizontal, 1e-6)))\n\npose_warnings = []\nfor side in ("left", "right"):\n    angle = arm_drop(side)\n    if angle is not None and angle > 20.0:\n        pose_warnings.append(f"{{side}} arm rest pose drops {{angle:.1f}} degrees; normalize to T/A-pose before production VRM export.")\n\nif DATA.get("glb_path"):\n    bpy.context.view_layer.objects.active = arm_obj\n    bpy.ops.export_scene.gltf(filepath=DATA["glb_path"], export_format="GLB", export_skins=True, export_morph=True)\n    print("Roblox Avatar Conversion Kit: exported GLB ->", DATA["glb_path"])\n\nprint(f"Roblox Avatar Conversion Kit: scene built; weighted {{weighted_vertices}} vertices; VRM mapping={{vrm_configured}}")\nfor warning in pose_warnings:\n    print("WARNING:", warning)\nprint("Review reconstructed weights and rest pose before final MMD/VRM production use.")\n'''
    Path(output).write_text(script, encoding="utf-8")
